package com.nigson.commerce.order;
import java.util.*;
import java.time.*;
import java.math.BigDecimal;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.*;
import com.nigson.commerce.inventory.StockLedger;
import com.nigson.commerce.cart.CartCheckout;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
/** Preserves verified late money even when released stock cannot be recovered. No provider calls. */
public final class JdbcOrderLifecycle implements OrderLifecycle {
 private final JdbcTemplate jdbc;private final OrderRepository repository;private final StockLedger stock;private final CartCheckout carts;private final AuditWriter audit;private final PlatformStore events;private final Clock clock;private final io.micrometer.core.instrument.MeterRegistry metrics;private final int ttl;
 public JdbcOrderLifecycle(JdbcTemplate jdbc,OrderRepository repository,StockLedger stock,CartCheckout carts,AuditWriter audit,PlatformStore events,Clock clock,io.micrometer.core.instrument.MeterRegistry metrics,int ttl){this.jdbc=jdbc;this.repository=repository;this.stock=stock;this.carts=carts;this.audit=audit;this.events=events;this.clock=clock;this.metrics=metrics;this.ttl=ttl;if(ttl<60||ttl>3600)throw new IllegalArgumentException("ORDER_RESERVATION_TTL_INVALID");}
 private UUID command(UUID transaction,String effect){return UUID.nameUUIDFromBytes((transaction+":"+effect).getBytes(java.nio.charset.StandardCharsets.US_ASCII));}
 public OrderValues.Order settled(UUID order,UUID correlation){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("LOCAL_TRANSACTION_REQUIRED");if(correlation==null)throw ApiValues.invalid();ApiValues.uuid(correlation.toString());jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");var before=repository.find(order,true);var truths=jdbc.queryForList("SELECT t.id,o.party_id,o.organization_id,o.cart_id,m.code,o.hold_reason FROM commerce.sales_order o JOIN commerce.market m ON m.id=o.market_id JOIN commerce.payment_attempt a ON a.order_id=o.id JOIN commerce.payment_transaction t ON t.attempt_id=a.id WHERE o.id=? AND a.provider='PAYSTACK' AND a.state='SUCCEEDED' AND a.verified_at IS NOT NULL AND a.expected_amount=o.grand_total AND t.settled_amount=a.expected_amount AND a.currency_code=o.currency_code AND t.currency_code=a.currency_code AND a.provider_mode=t.provider_mode AND a.provider_mode=CASE o.carrier_snapshot->>'mode' WHEN 'SANDBOX' THEN 'TEST' ELSE o.carrier_snapshot->>'mode' END AND t.provider_status='success'",order);if(truths.size()!=1)throw OrderValues.rule();var truth=truths.getFirst();UUID payment=(UUID)truth.get("id");boolean financialBefore=Set.of("PAID","PARTIALLY_REFUNDED","REFUNDED").contains(before.paymentStatus());if(financialBefore){if(!Set.of("PAID","PROCESSING","SHIPPED","DELIVERED","PAYMENT_HOLD","REFUNDING","REFUNDED").contains(before.status()))throw OrderValues.rule();if(truth.get("cart_id")!=null)carts.converted(order,correlation);return before;}if(!Set.of("PENDING","CANCELLED","PAYMENT_HOLD").contains(before.status())||before.version()==Long.MAX_VALUE)throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);
  var references=jdbc.queryForList("SELECT b.location_id,s.id AS sku_id,s.product_id,r.status FROM commerce.inventory_reservation r JOIN commerce.inventory_balance b ON b.id=r.balance_id JOIN commerce.sku s ON s.id=b.sku_id WHERE r.order_id=? ORDER BY b.id LIMIT 101",order);if(references.size()>100)throw OrderValues.rule();
  if(references.stream().allMatch(r->r.get("status").equals("RELEASED"))){for(String field:List.of("location_id","product_id","sku_id")){String table=field.equals("location_id")?"stock_location":field.equals("product_id")?"product":"sku";var ids=references.stream().map(r->(UUID)r.get(field)).distinct().sorted(Comparator.comparing(UUID::toString)).toList();for(UUID id:ids)jdbc.query("SELECT id FROM commerce."+table+" WHERE id=? FOR SHARE",(r,n)->r.getObject(1,UUID.class),id);}}
  var reservations=jdbc.queryForList("SELECT r.balance_id,r.quantity,r.status,b.sku_id,b.on_hand-b.reserved-b.allocated AS available FROM commerce.inventory_reservation r JOIN commerce.inventory_balance b ON b.id=r.balance_id WHERE r.order_id=? ORDER BY b.id LIMIT 101 FOR UPDATE OF b,r",order);if(reservations.isEmpty()||reservations.size()>100)throw OrderValues.rule();boolean reserved=reservations.stream().allMatch(r->r.get("status").equals("RESERVED"));boolean released=reservations.stream().allMatch(r->r.get("status").equals("RELEASED"));if(!reserved&&!released)throw OrderValues.rule();boolean held=truth.get("hold_reason")!=null;boolean recoverable=reserved&&!held;
  if(released){recoverable=!held;for(var r:reservations){boolean current=Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.inventory_balance b JOIN commerce.stock_location l ON l.id=b.location_id JOIN commerce.sku s ON s.id=b.sku_id JOIN commerce.product p ON p.id=s.product_id WHERE b.id=? AND l.active AND s.active AND s.deleted_at IS NULL AND p.status='ACTIVE' AND p.deleted_at IS NULL)",Boolean.class,r.get("balance_id")));if(!current||((BigDecimal)r.get("available")).compareTo((BigDecimal)r.get("quantity"))<0)recoverable=false;}}
  String subject="order-settlement";if(released&&recoverable){jdbc.update("UPDATE commerce.sales_order SET status='PAYMENT_HOLD',payment_status='PAID',fulfillment_status='HOLD',hold_reason='STOCK_UNAVAILABLE' WHERE id=?",order);var quantities=new LinkedHashMap<UUID,String>();for(var r:reservations)quantities.put((UUID)r.get("balance_id"),com.nigson.commerce.pricing.PricingValues.decimal((BigDecimal)r.get("quantity")));stock.reserve(order,quantities,clock.instant().truncatedTo(java.time.temporal.ChronoUnit.MICROS).plusSeconds(ttl),command(payment,"LATE_RESERVE"),subject,correlation);}
  String status=recoverable?"PAID":"PAYMENT_HOLD";jdbc.update("UPDATE commerce.sales_order SET status=?,payment_status='PAID',fulfillment_status=?,hold_reason=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",status,recoverable?"UNFULFILLED":"HOLD",recoverable?null:held?truth.get("hold_reason"):"STOCK_UNAVAILABLE",java.sql.Timestamp.from(clock.instant()),subject,order);if(recoverable)stock.allocate(order,command(payment,"ALLOCATE"),subject,correlation);if(truth.get("cart_id")!=null)carts.converted(order,correlation);jdbc.update("INSERT INTO commerce.order_status_history(id,created_by,order_id,previous_status,new_status,reason) VALUES (?,?,?,?,?,?)",EventCodec.uuid7(clock.instant()),subject,order,before.status(),status,recoverable?"Independently verified payment and stock allocation":"Verified financial truth retained; fulfillment remains held");audit.append(subject,AuditValues.ActorKind.SYSTEM,AuditValues.Action.ORDER_SETTLEMENT,AuditValues.Resource.ORDER,order,correlation,AuditValues.Reason.VERIFIED_PROVIDER,Map.of("state",before.status(),"version",before.version()),Map.of("state",status,"version",before.version()+1),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.order.commands","operation",status.equals("PAID")?"SETTLE":"HOLD").increment();}});
  if(!financialBefore){Instant now=clock.instant();var event=new LinkedHashMap<String,Object>();event.put("event_id",EventCodec.uuid7(now));event.put("event_type","order.paid.v1");event.put("schema_version",1);event.put("producer","commerce");event.put("occurred_at",now);event.put("aggregate_id",order);event.put("aggregate_version",before.version()+1);event.put("organization_id",truth.get("organization_id"));event.put("correlation_id",correlation);event.put("traceparent",null);var payload=new LinkedHashMap<String,Object>();payload.put("order_id",order);payload.put("party_id",truth.get("party_id"));payload.put("organization_id",truth.get("organization_id"));payload.put("currency",before.currency());payload.put("total",before.totals().grandTotal());payload.put("payment_transaction_id",payment);event.put("payload",payload);events.append(EventCodec.JSON.writeValueAsString(event),subject);}
  return repository.find(order,false);
 }
}
